"""Independent geometry for crystal cells of any system (checker side; imports no generation code).

Different methods from the generator (task_families/cell.py):
  - geometry from the metric tensor G (distance^2 = df' G df) and its numerical inverse for d-spacings,
    instead of lattice and reciprocal vectors;
  - its own CIF expansion (character scanner for symmetry operations), used to confirm that the student
    table is exactly the symmetry-expanded source: a reader bug in the generator cannot hide behind a
    checker that only trusts the table.
"""
import math
import re
from fractions import Fraction

import numpy as np

from .common import need, find

HEADER = re.compile(r'cell a = ([\d.]+) b = ([\d.]+) c = ([\d.]+) angstrom, alpha = ([\d.]+) beta = ([\d.]+) gamma = ([\d.]+) degree')
MATCH_TOL = 2e-4      # fractional: table vs own CIF expansion (the generator snaps 0.3333 to 1/3)


def parse_table(text):
    """(params or None, rows) from a fractional-cell table; params is None for the cubic header."""
    lines = text.splitlines()
    rows = [(r[0], [float(x) for x in r[1:]]) for r in (l.split() for l in lines[1:] if l.strip())]
    m = HEADER.search(lines[0])
    if not m:
        return None, rows
    return dict(zip(('a', 'b', 'c', 'alpha', 'beta', 'gamma'), (float(x) for x in m.groups()))), rows


def metric(p):
    ca, cb, cg = (math.cos(math.radians(p[k])) for k in ('alpha', 'beta', 'gamma'))
    a, b, c = p['a'], p['b'], p['c']
    return np.array([[a * a, a * b * cg, a * c * cb], [a * b * cg, b * b, b * c * ca], [a * c * cb, b * c * ca, c * c]])


def distance(G, f, g):
    v = np.array(g, dtype=float) - np.array(f, dtype=float)
    return math.sqrt(float(v @ G @ v))


def d_spacing(Ginv, hkl):
    h = np.array(hkl, dtype=float)
    return 1 / math.sqrt(float(h @ Ginv @ h))


def _value(token):
    return float(token.split('(')[0])


def _symop(text):
    """Character scanner: returns three (coefficients over x, y, z; translation) with fractions."""
    out = []
    for part in text.replace(' ', '').lower().split(','):
        coeff, shift, sign, number = [Fraction(0)] * 3, Fraction(0), 1, ''
        for ch in part + '+':
            if ch in 'xyz':
                coeff['xyz'.index(ch)] += sign * (Fraction(number) if number else 1)
                number, sign = '', 1
            elif ch in '+-':
                if number:
                    shift += sign * Fraction(number)
                number, sign = '', (1 if ch == '+' else -1)
            elif ch != '*':
                number += ch
        out.append((coeff, shift))
    need(len(out) == 3, 'Bad symmetry operation: ' + text)
    return out


def cif_cell(path):
    """Cell parameters and the symmetry-expanded atoms of a CIF, read with this module's own parser."""
    text = path.read_text(encoding='utf-8')
    params = {k: _value(find(r'_cell_(?:length|angle)_%s\s+(\S+)' % k, text, 'CIF lacks ' + k).group(1))
              for k in ('a', 'b', 'c', 'alpha', 'beta', 'gamma')}
    ops, sites = [], []
    tags, state = [], None                        # state: None (outside a loop), 'tags', 'rows'
    for raw in text.splitlines():
        line = raw.strip()
        if line == 'loop_':
            tags, state = [], 'tags'
            continue
        if line.startswith('_'):
            if state == 'tags':
                tags.append(line)
            else:
                state = None                      # a plain data item after the rows ends the loop
            continue
        if state is None or not line or line.startswith('#'):
            continue
        state = 'rows'
        values = re.findall(r"'[^']*'|\"[^\"]*\"|\S+", line)
        if len(values) != len(tags):
            continue
        row = dict(zip(tags, (v.strip('\'"') for v in values)))
        op = row.get('_symmetry_equiv_pos_as_xyz') or row.get('_space_group_symop_operation_xyz')
        if op:
            ops.append(_symop(op))
        if '_atom_site_fract_x' in row:
            element = re.match(r'[A-Z][a-z]?', row.get('_atom_site_type_symbol') or row['_atom_site_label']).group(0)
            sites.append((element, [_value(row['_atom_site_fract_' + k]) for k in 'xyz']))
    need(ops and sites, 'CIF symmetry operations or sites not found')
    atoms = []
    for element, f in sites:
        for op in ops:
            g = [(float(sum(c * x for c, x in zip(coeff, f)) + shift)) % 1.0 for coeff, shift in op]
            if not any(e == element and all(min(abs(x - y), 1 - abs(x - y)) < MATCH_TOL for x, y in zip(g, h)) for e, h in atoms):
                atoms.append((element, g))
    return params, atoms


def same_cell(params, rows, path):
    """The student table must be exactly the symmetry-expanded CIF (parameters and every atom)."""
    src_params, src_atoms = cif_cell(path)
    need(all(abs(params[k] - src_params[k]) < 1e-4 for k in params), 'Cell parameters differ from the CIF')
    need(len(rows) == len(src_atoms), 'Table has %d atoms, the expanded CIF %d' % (len(rows), len(src_atoms)))
    for e, f in rows:
        need(any(e == s and all(min(abs(x - y) % 1, 1 - abs(x - y) % 1) < MATCH_TOL for x, y in zip(f, g)) for s, g in src_atoms),
             'Table atom %s %s not in the expanded CIF' % (e, f))
    return len(src_atoms)

checker_code.checkers/common.py:
"""Shared helpers for independent answer checkers.

Independence rule: nothing under checkers/ imports the question-generation code
(task_families, family_engine, template_engine, choice_engine or tools). A checker
sees only what the tested model sees (question text, attached inputs, options) plus
the answer key, and recomputes with its own implementation. Provenance checks may
read the public source asset named in the answer key and verify its SHA-256.
"""
import hashlib
import math
import re
from decimal import Decimal, ROUND_HALF_UP, localcontext
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
VERSION = '0.1.0'
LABELS = ['A', 'B', 'C', 'D']
# Answer-key vocabulary that must never appear in a student packet.
FORBIDDEN_KEYS = {'correct_label', 'is_correct', 'option_audit', 'reason', 'source_id', 'numeric_answer',
                  'explanation', 'excluded_candidates', 'rank', 'checks'}


class CheckError(Exception):
    """A check that fails; the message is reported verbatim."""


def need(condition, message):
    if not condition:
        raise CheckError(message)


def find(pattern, text, message, flags=0):
    match = re.search(pattern, text, flags)
    need(match is not None, message)
    return match


def read_xyz(text):
    """Returns [(element, (Decimal x, y, z))]; strict count and row format."""
    lines = text.splitlines()
    need(len(lines) >= 3 and lines[0].strip().isdigit(), 'XYZ header invalid')
    rows = [line.split() for line in lines[2:] if line.strip()]
    need(len(rows) == int(lines[0]), 'XYZ atom count does not match rows')
    atoms = []
    for row in rows:
        need(len(row) == 4 and row[0].isalpha(), 'XYZ row must be element x y z')
        coords = tuple(Decimal(v) for v in row[1:])
        need(all(c.is_finite() for c in coords), 'Nonfinite coordinate')
        atoms.append((row[0].capitalize(), coords))
    return atoms


def dist(p, q):
    with localcontext() as ctx:
        ctx.prec = 40
        return sum((a - b) ** 2 for a, b in zip(p, q)).sqrt()


def vec(p, q):
    """q - p as floats."""
    return [float(b) - float(a) for a, b in zip(p, q)]


def dot(u, v):
    return math.fsum(a * b for a, b in zip(u, v))


def cross(u, v):
    return [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]


def rounded(value, decimals):
    return Decimal(str(value)).quantize(Decimal(1).scaleb(-decimals), rounding=ROUND_HALF_UP)


def sha256_file(rel):
    path = (ROOT / 'docs' / rel).resolve()
    need(path.is_relative_to((ROOT / 'docs/assets').resolve()), 'Evidence asset outside docs/assets')
    need(path.exists(), 'Evidence asset missing: ' + rel)
    return hashlib.sha256(path.read_bytes()).hexdigest(), path


def verify_hashes(key):
    """Every reviewer-side asset named in the key must match its recorded SHA-256."""
    paths = {}
    for rel, digest in key['input_hashes'].items():
        actual, path = sha256_file(rel)
        need(actual == digest, 'Asset hash mismatch: ' + rel)
        paths[rel] = path
    return paths


def packet_shape(packet):
    need([o['label'] for o in packet['options']] == LABELS, 'Options must be exactly A, B, C, D')
    need(len({o['value'] for o in packet['options']}) == 4, 'Duplicate option values')
    leaked = FORBIDDEN_KEYS & _keys(packet)
    need(not leaked, 'Answer-key fields in student packet: ' + ', '.join(sorted(leaked)))


def _keys(obj):
    if isinstance(obj, dict):
        return set(obj) | set().union(*(_keys(v) for v in obj.values()))
    if isinstance(obj, list):
        return set().union(*(_keys(v) for v in obj)) if obj else set()
    return set()


def gap(a, b, period=None):
    d = abs(a - b)
    if period is not None:
        d = min(d % period, period - d % period)
    return d


def judge_numeric(packet, key, value, period=None):
    """Recomputed value vs. options and key: exactly one option equals the rounded value,
    the other three lie outside the tolerance, and key label / numeric key agree."""
    numeric = key['numeric_answer']
    decimals, tol = numeric['decimals'], Decimal(numeric['tolerance'])
    expected = rounded(value, decimals)
    exact = Decimal(repr(value)) if isinstance(value, float) else Decimal(value)
    units = {o.get('unit') for o in packet['options']}
    need(units == {numeric['unit']}, 'Option units differ from the answer unit')
    for o in packet['options']:
        need(re.fullmatch(r'-?\d+\.\d{%d}' % decimals if decimals else r'-?\d+', o['value']) is not None,
             'Option %s not shown with %d decimals' % (o['label'], decimals))
    hits = [o['label'] for o in packet['options'] if gap(Decimal(o['value']), exact, period) <= tol]
    need(len(hits) == 1, 'Recomputed value matches %d options (need exactly 1)' % len(hits))
    label = hits[0]
    shown = next(o['value'] for o in packet['options'] if o['label'] == label)
    need(Decimal(shown) == expected or (period and gap(Decimal(shown), expected, period) == 0),
         'Matching option %s is not the rounded recomputed value %s' % (shown, expected))
    need(Decimal(numeric['value']) == expected, 'Numeric key %s != recomputed %s' % (numeric['value'], expected))
    need(key['correct_label'] == label, 'Key label %s != recomputed label %s' % (key['correct_label'], label))
    nearest = min(gap(Decimal(o['value']), exact, period) for o in packet['options'] if o['label'] != label)
    q = Decimal('1e-10')
    return dict(recomputed=str(exact.quantize(q)), rounded=str(expected), label=label,
                nearest_distractor_gap=str(nearest.quantize(q)))

